-- The notable-NPC gap, last part: the named people Phase 2a missed in Juicer
-- Uprising, Federation of Magic, Free Quebec and New West, and the one each in
-- Underseas and Mystic Russia - rows for notable_npcs (migration 072) and their
-- attacks in stat_attacks (owner_kind 'notable_npc').
--
-- One-off data script, run once per environment. NOT a migration.
--
-- FOUND by diffing every Real / True / Full Name line and numeric experience
-- level in these books against the notable NPCs already live. Phase 2a took nine
-- Federation of Magic people, six Free Quebec, six New West and two Juicer
-- Uprising; these are the rest:
-- - Juicer Uprising: Vanessa Death-Giver, the Redstone Twins (Angel and Cherub,
--   a row each), Cagliostro Smith, the Slayer, George Hornesby, Julian the First.
-- - Federation of Magic: Bloodmist, Brok Redman, Cracius the Cunning, Hugh
--   Madding.
-- - Free Quebec: Jacques LeFevre, Elaine Jeunet.
-- - New West: Kenneth Sprite.
-- - Underseas: Captain Nemo-2.
-- - Mystic Russia: Old Man Morozko, King of the Frost Demons - the book gives
--   him only one inline line (12th level, 2000 M.D.C., anarchist), so most of
--   his row is empty by design.
--
-- A rank or office is the title, not the name (Elaine Jeunet, Kenneth Sprite),
-- as in #1164. A compound level ("equal to a 5th level Fire Warlock and 9th level
-- warrior") takes the first number, as every row does.
--
-- EXTRACTED by book-extract-workers, every number read off a 200 dpi render
-- rather than the OCR cache, which carries the digit cipher. RECONCILED by
-- book-reconcile against the renders, row by row; its corrections are applied.
-- description, disposition and natural_abilities are short paraphrases, checked
-- against the cache by an 8-word shingle test - no sentence is the book's.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-notable-npcs-juicer-uprising-and-others.sql
--
-- BY BOOK:
--   Rifts World Book 10: Juicer Uprising (7): Vanessa Death-Giver, Angel, Cherub,
--     Cagliostro Smith, The Slayer, George Hornesby, Julian the First
--   Rifts World Book 16: Federation of Magic (4): Bloodmist, Brok Redman, Cracius The
--     Cunning, Hugh Madding
--   Rifts World Book 22: Free Quebec (2): Jacques LeFevre, Elaine Jeunet
--   Rifts World Book 14: New West (1): Kenneth Sprite
--   Rifts World Book 7: Underseas (1): Captain Nemo-2
--   Rifts World Book 18: Mystic Russia (1): Old Man Morozko

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'vanessa-death-giver', 'Vanessa Death-Giver', NULL, 'Current Leader of the Valkyri', 'rifts', NULL, 'Juicer', 7, 'Aberrant with unscrupulous leanings.', NULL, NULL, NULL, '{"IQ":17,"ME":15,"MA":13,"PS":28,"PP":27,"PE":29,"PB":11,"Spd":95}', 82, 327, NULL, 8, 43, NULL, NULL, '{"attacks":7,"initiative":4,"strike":8,"parry":11,"dodge":11,"roll":9,"pull":9}', 'Level of Experience printed as 7th level Juicer (4th year) - four years into the Juicer conversion. +17 to S.D.C. damage; +7 to save vs. magic. M.D.C. is from equipment only, not a personal pool: Special Juicer Plate Armor (55 M.D.C.) combined with a stolen Splugorth Blind Warrior Woman energy field (100 M.D.C.). Horror Factor: None usually; H.F. 8 in full battle gear and combat mask (conditional, not a flat value).', '[{"name":"Basic radio","pct":93},{"name":"Wilderness survival","pct":73},{"name":"Land navigation","pct":72},{"name":"Pilot (tank and APC)","pct":67},{"name":"Motorcycle","pct":98},{"name":"Prowl","pct":73}]', 'Combat Jump Bike (see the new skills section); assorted W.P.s including sword and paired weapons. Hand to hand: assassin, boxing, wrestling.', 'All Juicer abilities and powers (see Rifts RPG, page 69). Vulnerable: the usual Juicer problems, plus Metabolic Induced Voracity - she must eat 10,000-20,000 calories a day, and makes a show of it.', 'None, other than a general knowledge of anti-mage tactics.', 'Minor psionic: mind block and telepathy.', NULL, NULL, 'Lesser rune sword (evil alignment, 5D6 M.D., has all the usual rune sword powers); three vibro-swords (2D6 M.D. each); JA-12 laser rifle or WI-GL4 revolving grenade launcher for ranged combat; personalized Iron Maiden APC (camouflage, three long-range missile launchers, one missile each); Tarantula Jump Bike; Special Juicer Plate Armor (55 M.D.C.) with a painted face mask (H.F. 7) and a stolen Blind Warrior Woman energy field (100 M.D.C.).', 'Over a million credits in her personal account, plus access to 1D4+2 million more through the mercenary company.', 'Distant and chilly, menacing without raising her voice when challenged; she no longer respects men and loathes the Coalition army, which she holds responsible for the loss of everyone she loved.', 'The Valkyri; Lt. Damian Crow of Crow''s Commandoes, a former lover who parted on bad terms but still owes/is owed a favor.', 'The Coalition States military, which she blames for the deaths of everyone she has cared for.', 'A tall, athletic, red-haired leader of the all-female Valkyri mercenary band, her face almost always hidden behind a painted mask.', 'Rifts World Book 10: Juicer Uprising p.90-91');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'angel-redstone', 'Angel', 'Angel Redstone', 'one of the Redstone Twins', 'rifts', NULL, 'Hyperion Juicer', 5, 'Anarchist with evil leanings.', NULL, NULL, NULL, '{"IQ":14,"ME":20,"MA":17,"PS":22,"PP":28,"PE":19,"PB":17,"Spd":98}', 44, 105, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":7,"strike":10,"parry":14,"dodge":14,"roll":8,"pull":8}', 'Plus 2 save vs magic. M.D.C. by body armor only; no personal M.D.C. pool. Standard Juicer vulnerabilities/penalties apply.', '[{"name":"Wilderness Survival","pct":65},{"name":"Streetwise","pct":45}]', 'Motorcycle (+90%) and prowl (+55%) are printed as bonuses rather than base skill percentages; assorted W.P.s. Hand to hand: expert and boxing.', 'All Hyperion Juicer abilities.', NULL, NULL, NULL, NULL, 'Favors laser rifles, owning half a dozen different types from pulse rifles to sniper rifles; rides a Highwayman motorcycle when taking a break, otherwise prefers to run.', NULL, 'The tougher-minded twin: she recovered from months of mistreatment, does not fear men, and has a cruel streak - she treats men as fools to be toyed with and beaten, and will go out of her way to ruin a foe.', 'None but each other, Vanessa, and their fellow Valkyri.', NULL, 'One of the Redstone Twins, elfin-featured Hyperion Juicer sisters with light brown hair and green eyes who joined Vanessa to found the Valkyri.', 'Rifts World Book 10: Juicer Uprising p.91');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'cherub-redstone', 'Cherub', 'Cherub Redstone', 'one of the Redstone Twins', 'rifts', NULL, 'Hyperion Juicer', 5, 'Anarchist with evil leanings.', NULL, NULL, NULL, '{"IQ":16,"ME":14,"MA":18,"PS":24,"PP":26,"PE":21,"PB":17,"Spd":103}', 50, 98, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":7,"strike":9,"parry":13,"dodge":13,"roll":8,"pull":8}', 'Plus 3 save vs magic. M.D.C. by body armor only; no personal M.D.C. pool. Standard Juicer vulnerabilities/penalties apply.', '[{"name":"Wilderness Survival","pct":65},{"name":"Streetwise","pct":45}]', 'Motorcycle (+90%) and prowl (+55%) are printed as bonuses rather than base skill percentages; assorted W.P.s. Hand to hand: expert and boxing.', 'All Hyperion Juicer abilities.', NULL, NULL, NULL, NULL, 'Favors laser rifles, owning half a dozen different types from pulse rifles to sniper rifles; rides a Highwayman motorcycle when taking a break, otherwise prefers to run.', NULL, 'The more wounded twin: still scarred by her captivity, she masks a fear of men with temper and aggression; no weakling, but she defers to those she looks up to, Angel and Vanessa above all.', 'None but each other, Vanessa, and their fellow Valkyri.', NULL, 'One of the Redstone Twins, elfin-featured Hyperion Juicer sisters with light brown hair and green eyes who joined Vanessa to found the Valkyri.', 'Rifts World Book 10: Juicer Uprising p.91');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'cagliostro-smith', 'Cagliostro Smith', NULL, 'Ley Line Walker and Human Supremacist', 'rifts', NULL, 'Ley Line Walker', 10, 'Aberrant', NULL, NULL, NULL, '{"IQ":22,"ME":13,"MA":8,"PS":13,"PP":12,"PE":10,"PB":12,"Spd":14}', 33, 16, NULL, 168, NULL, NULL, NULL, '{"attacks":4,"strike":1,"parry":2,"dodge":2,"roll":2,"pull":2}', 'Plus 2 save vs magic; plus 2 to spell strength; plus 4 to save vs horror factor. M.D.C. only by armor or spell; no personal M.D.C. pool. No initiative bonus is printed.', '[{"name":"Land navigation","pct":88},{"name":"Wilderness survival","pct":93},{"name":"Demon and monster lore","pct":93},{"name":"Faerie lore","pct":88},{"name":"Language: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Language: Dragonese/Elven","pct":98}]', 'W.P. Energy Pistol. Hand to hand: basic and boxing.', 'Read and sense ley lines, Rifts and magic energy; ley line transmission; ley line phasing, drifting and rejuvenation; create ley line observation ball; plus see magical abilities.', 'Has learned all spells from levels 1-7, plus anti-magic cloud, commune with spirits, create magic scroll, negate magic, talisman and wards.', NULL, NULL, NULL, 'Favored sidearm is a Wilks 320 laser pistol; wears plastic-man armor under his robes normally, or a stolen suit of Dead Boy Armor (80 M.D.C., old style, painted red and yellow striped) when expecting combat.', '500,000 credits in personal funds; reasonable access to approximately ten million credits through the Society of Sages.', 'Sees himself as a defender of humankind, similar to Emperor Proseks supporters except that he views magic as a useful tool. Friendly, reasonable and honorable with humans, but deeply prejudiced against D-Bees and other non-humans, whom he does not extend that same honor to.', 'The Society of Sages; several members of the Kingsdale Senate, including the godling Arcadia.', 'D-Bees and dragons in general, and the Cult of Dragonwright in particular; an unnamed rival, rumored to be a dragon or inhuman creature, who once defeated and exiled him from his petty kingdom.', 'A Ley Line Walker sorcerer of unconfirmed origin, formerly of the Federation of Magic and once ruler of his own petty kingdom, now a mid-level handler for the Society of Sages.', 'Rifts World Book 10: Juicer Uprising p.93');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'slayer-dragon-juicer', 'The Slayer', NULL, 'Former Cyber-Knight, now a Dragon Juicer', 'rifts', NULL, 'Cyber-Knight and Dragon Juicer', 3, 'Aberrant, although some of his formerly principled tendencies come to the surface once in a while.', NULL, NULL, NULL, '{"IQ":12,"ME":17,"MA":13,"PS":35,"PP":30,"PE":28,"PB":9,"Spd":53}', NULL, NULL, 198, 31, NULL, NULL, NULL, '{"attacks":8,"initiative":4,"strike":10,"parry":13,"dodge":13,"roll":9,"pull":9}', 'Plus 7 to save vs magic, plus 4 to save vs psionics and mind control, plus 6 to save vs poison, plus 10 to save vs horror factor. Damage is as per supernatural P.S. or weapon, no fixed number printed. P.S. of 35 is noted as supernatural. Horror Factor is explicitly printed as None.', '[{"name":"Language: Dragonese/Elf","pct":98},{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Lore: Demon","pct":98},{"name":"Lore: Juicer","pct":98}]', 'Gymnastics, climb, swim, land navigation, horsemanship, W.P. sword, W.P. archery and targeting, W.P. energy rifle, W.P. heavy energy (no percentages printed). Hand to hand: martial arts, boxing and wrestling.', 'All Dragon Juicer abilities and Cyber-Knight powers except psi-sword. Vulnerable: affected by every anti-dragon power; short life span; addicted to dragon blood.', NULL, 'Has lost his psi-sword and other psionic powers.', NULL, NULL, 'A lesser rune sword acquired on his last mission; favors vibro-blades and other melee weapons; ranged weapon of choice is a Naruni Enterprises Plasma Cartridge Rifle; wears Dragon Skin Armor (100 M.D.C.).', 'Almost a million credits, rarely used unless it will make a mission easier; expenses usually covered by his employers.', 'A driven, obsessed, humorless man who represses his emotions as distracting weaknesses. Respects courage and strength and will aid a worthy warrior facing hopeless odds, but cannot tolerate cowardice in himself or anyone else, and would rather die than act the coward.', 'The Society of Sages, his employer; works alongside Cagliostro Smith.', 'Dragons in general and followers of the Cult of Dragonwright; has killed five human cultists in the course of his missions.', 'A former Cyber-Knight remade as a Dragon Juicer to hunt dragons for the Society of Sages - a single-minded agent and among the finest unarmed fighters alive.', 'Rifts World Book 10: Juicer Uprising p.93-94');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'george-hornesby', 'George Hornesby', NULL, 'Governor of Newtown', 'rifts', NULL, 'Glitter Boy pilot and merchant', 5, 'Miscreant', 'In his fifties', NULL, NULL, '{"IQ":17,"ME":12,"MA":22,"PS":15,"PP":16,"PE":19,"PB":13,"Spd":14}', 49, 39, NULL, 13, NULL, NULL, NULL, '{"attacks":5,"strike":2,"parry":5,"dodge":5,"roll":4}', '55 percent trust/intimidate; critical strike and knockout/stun on an unmodified 18-20; plus 2 vs magic and poison. No initiative bonus is printed. M.D.C. is entirely equipment-based: 770 M.D.C. while piloting his Glitter Boy suit, or 30 M.D.C. from light M.D. armor worn under his clothes day-to-day; he has no personal M.D.C. pool.', NULL, 'Hand to Hand: Expert, Robot Combat: Elite, and boxing.', NULL, NULL, NULL, NULL, NULL, 'Owns and maintains a Glitter Boy suit (770 M.D.C.) as his preferred combat tool; wears light M.D. armor (30 M.D.C.) under his clothes on normal days; has access to all UTI products and any hand-gun or rifle ever made.', 'A personal fortune of 150 million credits in cash and over a billion in personal property and landholdings, plus an income of 25 million credits a year from business interests.', 'A ruthless, conniving charmer skilled at understanding and exploiting people; still in excellent shape and unafraid of violence despite his age, with a tough guy attitude that has made others, including General Orly, back down.', 'UTI and its leader Andrew Anderson, on whose well-being his fate depends; the Black Market, which owes him favors for his turning a blind eye to their activities. Has 20 personal retainers acting as bodyguards and enforcers: 10 Headhunters (levels 3-6), five Wilderness Scouts (levels 4-8), and five full-conversion Borgs (levels 4-7).', NULL, 'The wealthy, self-made Governor of Newtown, a former Glitter Boy mercenary turned merchant-politician secretly partnered with the D-Bee newcomers who built the citys technology.', 'Rifts World Book 10: Juicer Uprising p.128');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'julian-the-first', 'Julian the First', NULL, 'Leader of the Juicer Army of Liberation', 'rifts', NULL, 'Mega-Juicer', 8, 'Aberrant', NULL, NULL, NULL, '{"IQ":16,"ME":14,"MA":23,"PS":32,"PP":21,"PE":28,"PB":12,"Spd":87}', NULL, NULL, 143, 21, NULL, NULL, NULL, NULL, 'No attacks per melee round, combat bonuses, or skills are printed for this entry.', NULL, NULL, 'Supernatural strength and endurance; gets an automatic parry or dodge on all attacks; regenerates 2D6 M.D.C. every hour; virtually impervious to pain, as per the normal Juicer.', NULL, NULL, NULL, NULL, NULL, NULL, 'Driven by a vow to bring down the Coalition States and aware he has only 10-13 months left to live, he wants to inflict maximum damage before he dies. Not a berserker or suicidal fanatic; he wants to win, crafts careful plans, will not waste his men needlessly, and refuses any deal with the Coalition.', 'The Juicer Army of Liberation; John Slaughter and other Juicer leaders who back his plan; formerly his wife Diane Lightning Strike Danforth, killed in a Coalition attack.', 'The Coalition States, especially Emperor Prosek.', 'A charismatic Mega-Juicer who seized control of the Juicer Army of Liberation after losing his mercenary band and wife to a Coalition attack, and who leads the Juicer Uprising against Newtown.', 'Rifts World Book 10: Juicer Uprising p.138-139');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'bloodmist', 'Bloodmist', NULL, 'Dunscon Bodyguard and Advisor (also known as Dunscons Blade and the Hellcat)', 'rifts', 'Raksasha greater demon (Raksasha Demon Lord)', NULL, 10, 'Diabolic', 'Thousands of years old', '6 feet, 2 inches tall (1.9 m)', '250 lbs. (112.5 kg), all muscle', '{"IQ":19,"ME":16,"MA":17,"PS":37,"PP":18,"PE":23,"PB":14,"Spd":40}', NULL, NULL, 900, 900, 600, NULL, 14, '{"initiative":4,"strike":6,"parry":6,"dodge":6,"roll":4}', 'Six physical or psionic attacks, or two attacks per round; critical strike on a natural 20; plus 4 on all saving throws.', '[{"name":"Basic Math","pct":98},{"name":"Advanced Math","pct":98},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: American","pct":98},{"name":"Literacy: Dwarven","pct":98},{"name":"Literacy: Simvan","pct":98},{"name":"Literacy: Demongogian","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Recognize Weapon Quality","pct":98},{"name":"Trap Construction","pct":90},{"name":"Trap/Mine Detection","pct":95},{"name":"Military Etiquette","pct":80},{"name":"Find Contraband","pct":80},{"name":"Streetwise","pct":60},{"name":"Seduction","pct":70},{"name":"Land Navigation","pct":98},{"name":"Swim","pct":98},{"name":"Climb","pct":90},{"name":"Dance","pct":90},{"name":"Sing","pct":75},{"name":"Demon Lore","pct":98},{"name":"Faerie Lore","pct":92},{"name":"Magic Lore","pct":92},{"name":"Radio: Basic","pct":98},{"name":"Computer Operation","pct":98},{"name":"Pilot Automobile","pct":70},{"name":"Pilot Hovercraft","pct":70},{"name":"Horsemanship: General","pct":70}]', 'All espionage skills at 98%. Climb also given as 90%/80%. W.P. sword, W.P. knife, W.P. blunt, W.P. targeting, W.P. paired weapons, W.P. energy rifle.', 'Nightvision 120 ft, keen normal vision, see the invisible, turn into mist at will, track by smell 45%, dimensional teleport 51%, bio-regeneration 4D6 M.D. per minute, resistant to fire and cold (magic fire/cold and M.D. plasma do half damage), teleport self plus up to 300 lbs up to five miles, magically knows all languages, shape change at will into any living creature 1-10 feet tall.', 'As a Raksasha Lord: all metamorphosis, protection, and illusionary magic, plus Exorcism, Manipulate Objects, Healing Touch, Armor of Ithan, Carpet of Adhesion, Blinding Flash, Fire Bolt, Fireblast, Deflect, Frostblade, Animate and Control Dead, Turn Dead, Death Trance, Aura of Death, Deathword, and Beat Insurmountable Odds. Spells cast at the equivalent of 4th level, spell strength 13.', '600 I.S.P.; possesses all psionic powers at 8th level proficiency.', NULL, NULL, 'A cache of minor magical/technological weapons; favorite is a SAMAS rail gun (and backpack) taken from a destroyed Coalition SAMAS; greater rune dagger Bloodletter (see attacks).', 'Personal treasure trove of gems/jewelry worth over 10 million credits, plus a million in universal credits.', 'Confident and manipulative; enjoys mind games and political intrigue more than open carnage, though he honestly respects and loyally serves Dunscon.', 'Lord Dunscon, other council members and demons, and other creatures of darkness.', 'The enemies of Lord Dunscon, plus vampires, alien intelligences, and humanoids in general.', 'Bloodmist is a Raksasha Demon Lord who serves as Lord Dunscons closest advisor, bodyguard, and emissary to the demon hordes.', 'Rifts World Book 16: Federation of Magic p.42-43');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'brok-redman', 'Brok Redman', NULL, 'Baal-Rog Advisor (also known as The Demon General)', 'rifts', 'Baal-Rog greater demon', NULL, 5, 'Aberrant', 'Hundreds of years old', '13 feet tall (3.9 m)', 'one ton of muscle and meanness', '{"IQ":18,"ME":19,"MA":17,"PS":38,"PP":18,"PE":21,"PB":7,"Spd":40}', NULL, NULL, 600, 325, NULL, NULL, 14, '{"pull":4,"roll":4,"strike":3,"parry":3,"dodge":3,"initiative":3}', 'Six physical attacks per melee, or three by magic. Favorite weapon is the magic fire whip. Plus 3 on magic saving throws, in addition to attribute bonuses.', '[{"name":"Basic Math","pct":92},{"name":"Advanced Math","pct":92},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Forgery","pct":45},{"name":"Intelligence","pct":88},{"name":"Track Humans","pct":50},{"name":"Wilderness Survival","pct":70},{"name":"Land Navigation","pct":80},{"name":"Swim","pct":60},{"name":"Climb","pct":80},{"name":"Dance","pct":80},{"name":"Streetwise","pct":80},{"name":"Demon and Monster Lore","pct":80},{"name":"Faerie Lore","pct":60},{"name":"Radio: Basic","pct":80},{"name":"Computer Operation","pct":60}]', 'Literate also in two other languages of choice. Climb also given as 80%/70%. W.P. chain, W.P. heavy energy.', 'Fly, nightvision 90 ft (can see in total darkness), see the invisible, turn invisible, track by smell 45%, dimensional teleport 57%, bio-regeneration 4D6 M.D. per minute, impervious to fire (including M.D. magic fire and plasma energy), magically knows all languages, can leap 50 feet without assistance from his wings.', 'All levels 1-4 fire elemental magic, plus fire whip (level 7), animate and control dead, turn dead, exorcism, remove curse, and heal wounds. Equal to a 5th level wizard. P.P.E. 325.', NULL, NULL, NULL, 'Relies mainly on cunning, strength and natural abilities, but uses man-made weapons and magic items when needed; prefers heavy weapons.', 'Personal treasure trove of gems/jewelry worth over 10 million credits, plus a half million in universal credits.', 'A bold, forceful natural leader, intelligent and disarmingly charming despite his frightening appearance; comfortable commanding forces of any size.', 'Lord Dunscon, other council members and demons, and other creatures of darkness.', 'The enemies of Lord Dunscon, plus vampires, alien intelligences, and humanoids in general.', 'Brok Redman is a Baal-Rog demon and the military strategist of Lord Dunscons High Council.', 'Rifts World Book 16: Federation of Magic p.45');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'cracius-the-cunning', 'Cracius The Cunning', NULL, 'Deevil Advisor', 'rifts', 'Deevil', NULL, 4, 'Miscreant', 'Hundreds of years old', '8 feet tall (2.4 m)', '500 pounds (225 kg)', '{"IQ":12,"MA":18,"ME":18,"PS":22,"PP":20,"PE":20,"PB":6,"Spd":40}', NULL, NULL, 170, 90, NULL, NULL, 14, '{"initiative":2,"strike":3,"parry":3,"dodge":2,"pull":3,"roll":3}', 'Six attacks per melee. Plus 2 on all magic saving throws, plus 6 to save vs Horror Factor, in addition to attribute bonuses.', '[{"name":"Escape Artist","pct":65},{"name":"Intelligence","pct":70},{"name":"Wilderness Survival","pct":80},{"name":"Land Navigation","pct":80},{"name":"Pick Pockets","pct":64},{"name":"Pick Locks","pct":70},{"name":"Palming","pct":55},{"name":"Concealment","pct":55},{"name":"Streetwise","pct":55},{"name":"Prowl","pct":50},{"name":"Swim","pct":50},{"name":"Climb","pct":80},{"name":"Literacy: Dragonese/Elven","pct":98},{"name":"Literacy: American","pct":98},{"name":"Language: Demongogian","pct":80},{"name":"Language: Spanish","pct":80},{"name":"Language: Euro","pct":80}]', 'Climb also given as 80%/70%. W.P. sword, W.P. blunt, W.P. energy pistol, W.P. energy rifle, all equal to 6th level proficiency.', 'Nightvision 60 ft (can see in total darkness), see the invisible, turn invisible at will, metamorphosis: human, track by smell 55%, dimensional teleport 63%, bio-regeneration 3D6 M.D. per minute, magically knows all languages, can leap 30 feet.', '90 P.P.E. All level one fire elemental magic plus turn dead, luck curse, phobia curse, compulsion, remove curse, heal wounds. Fourth level proficiency.', NULL, NULL, NULL, 'Relies mainly on cunning and smooth talking plus his natural abilities, but uses man-made weapons and magic items when the situation requires it.', 'Personal treasure trove worth four million credits, plus a quarter million in universal credits.', 'Cheerful and cocky, a bold risk-taker who stays cool under fire and is an excellent bluffer.', 'Lord Dunscon, Mestoph, other council members, deevils, and other creatures of darkness.', 'The enemies of Lord Dunscon, plus vampires, alien intelligences, and humanoids in general.', 'Cracius The Cunning is a Deevil who serves Lord Dunscon as diplomat, spy, and interrogator.', 'Rifts World Book 16: Federation of Magic p.45-46');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'hugh-madding', 'Hugh Madding', NULL, 'Battle Magus of the Mystic Triad', 'rifts', 'Human', 'Battle Magus', 10, 'Unprincipled', '42', '6 feet, 1 inch tall (1.8 m)', '200 lbs. (90 kg)', '{"IQ":15,"ME":14,"MA":9,"PS":24,"PP":17,"PE":18,"PB":11,"Spd":32}', 63, 45, NULL, 198, NULL, NULL, NULL, '{"initiative":3,"disarm":2,"roll":4,"pull":11,"strike":6,"parry":8,"dodge":8,"damage":12}', 'Eight physical or two spell attacks per melee round. Critical strike on an 18-20, paired weapons, body flip/throw, plus 1 to all aimed and called shots regardless of weapon type. Plus 1 to save vs mind control, plus 5 to save vs possession, plus 2 to save vs magic, plus 2 to save vs poison, plus 7 to save vs Horror Factor, plus 20 percent to save vs coma and death, plus 2 to save vs disease and poison. The plus 12 combat entry above is the printed S.D.C. damage bonus, not a Mega-Damage bonus.', '[{"name":"Horsemanship: General","pct":90}]', 'Boxing, wrestling, martial arts, pilot Earth Thunder and Fire Demon Automatons, W.P. sword, W.P. Staff, W.P. archery, W.P. energy rifle, W.P. heavy energy weapons, W.P. paired weapons, and W.P. sharpshooting with a bow as well as his magical energy blasts. Also fatigues at one third normal rate, can hold breath about 4 minutes, exceptional balance (+10%), can leap 10% farther.', NULL, 'Standard for a Battle Magus, including Lightblade, Frostblade and Invincible Armor. Spell strength 14.', NULL, NULL, NULL, 'A pair of Deathbringer swords and a Firestaff; always wears mystic armor.', NULL, 'Gruff, hardened and loyal; a realist who protects the idealistic Kara Zayne while doubting her dream can fully succeed.', 'Dweomer City, the Lords of Magic, Cyber-Knights, and the citizens of Magestar.', 'The Coalition, Grim Reapers, and Necromancers are among the most notable. Hates injustice and cruelty.', 'Hugh Madding is a grizzled veteran Battle Magus and the second member of the Mystic Triad who leads Magestars defenses.', 'Rifts World Book 16: Federation of Magic p.55-56');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'jacques-lefevre', 'Jacques LeFevre', 'Jacques LeFevre', 'First Fleet Commodore (also referred to as Admiral LeFevre)', 'rifts', NULL, 'sailor and ex-Privateer', 12, 'Aberrant', '92, looks about 70ish', '6 feet, 4 inches (1.92 m)', '220 lbs (98 kg)', '{"IQ":15,"MA":22,"ME":22,"PS":14,"PP":21,"PE":18,"PB":10,"Spd":10}', 61, 34, NULL, 9, NULL, NULL, NULL, '{"attacks":7,"initiative":8,"strike":7,"parry":7,"dodge":8,"roll":5,"damage":4}', 'Death Blow on a natural 20 (but only if trying to kill); plus 3 to save vs Horror Factor; knockout/stun on natural 17-20; 70 percent to trust/intimidate; plus 4 to save vs psionics; plus 2 to save vs magic; plus 6 percent to save vs death/coma.', '[{"name":"Language: American","pct":98},{"name":"Language: Techno-Can","pct":98},{"name":"Language: Old Quebec French","pct":75},{"name":"Basic Math","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Navigation","pct":98},{"name":"Pilot: Sailing Vessels","pct":98},{"name":"Pilot: Warships and Patrol Boats","pct":98},{"name":"Naval Tactics","pct":98},{"name":"Swimming","pct":98},{"name":"Literacy: American","pct":80},{"name":"Streetwise","pct":72},{"name":"Find Contraband","pct":86},{"name":"Recognize Weapon Quality","pct":75},{"name":"Lore: Demons and Monsters","pct":90},{"name":"Undersea Salvage","pct":80},{"name":"Intelligence","pct":72},{"name":"Computer Operations","pct":80},{"name":"Naval History","pct":98}]', 'Pilot: Ship at 98%/89%. Combat Skills: Hand to Hand: Assassin. Weapon Proficiencies: W.P. Energy Rifle, W.P. Energy Pistol, W.P. Knife, W.P. Sword.', NULL, NULL, NULL, NULL, 'Universal headjack and ear implant with amplified hearing, sound filtration, plus gyro-compass, depth gauge, clock calendar and toxic filter. Right hand, left arm, spleen and heart have at various times been replaced with cybernetic bio-systems.', 'Typically unarmed on the bridge but carries a personal energy pistol and rifle. Not trained in power armor combat but commands a detachment of Sea Dragons. Has access to all Free Quebec Navy equipment, special communications and surveillance equipment, men and resources; free rein of Navy facilities including the Dolbeau Shipyards, and up to medium-high level clearance at Army bases.', '2.1 million credits and a personal collection of Black Market weapons, artifacts and items worth another million; does not include his current pay or life-long pension of 10,000 credits a month. Owns a home in Free Quebec and a hunting lodge in the north.', 'A charismatic, hard-as-nails leader who inspires confidence, is willing to bend or ignore orders to protect his men, and is known for bold, lucky maneuvers.', NULL, NULL, 'Jacques LeFevre is a legendary ex-privateer turned Admiral who commands Free Quebecs First Fleet aboard the FQS Redeemer.', 'Rifts World Book 22: Free Quebec p.127-128');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'elaine-jeunet', 'Elaine Jeunet', 'Elaine Marie Jeunet', 'Captain; Renegade Soldier of the Quebec Army', 'rifts', NULL, 'CS Special Forces', 6, 'Aberrant, dedicated to her country but with her own twisted view of what is best for it', '24', '6 feet (1.8 m)', '150 lbs (all muscle; 67.5 kg)', '{"IQ":18,"MA":14,"ME":11,"PS":21,"PP":20,"PE":15,"PB":14,"Spd":21}', 37, 51, NULL, 9, NULL, NULL, NULL, '{"attacks":7,"initiative":3,"strike":5,"parry":7,"dodge":7,"roll":4,"pull":3,"damage":10}', 'Has the entangle combat maneuver; pin/incapacitate on natural 18-20; critical strike on natural 18-20; 80 percent to trust/intimidate.', '[{"name":"Literacy: American","pct":69},{"name":"Language: American","pct":98},{"name":"Basic Math","pct":94},{"name":"Radio: Basic","pct":89},{"name":"Radio: Scrambler","pct":74},{"name":"Climbing","pct":84},{"name":"Wilderness Survival","pct":74},{"name":"Land Navigation","pct":70},{"name":"Intelligence","pct":62},{"name":"Interrogation","pct":64},{"name":"Streetwise","pct":60},{"name":"Pilot Hovercycle","pct":89},{"name":"Pilot Robots and Power Armor","pct":85},{"name":"Lore: Demons and Monsters","pct":64},{"name":"Read Sensory Instruments","pct":74},{"name":"Detect Ambush","pct":69},{"name":"Military Etiquette","pct":79},{"name":"Computer Operations","pct":79}]', 'Climbing also given as 84%/74%. Running and Pilot: Robot Combat Elite (SAMAS all) listed without percentages. Combat Skills: Hand to Hand: Assassin, 6th level; Robot Combat: Elite (SAMAS); boxing; wrestling. Weapon Proficiencies: W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy, W.P. Knife, Sniper, Demolitions, Paired Weapons.', NULL, NULL, NULL, NULL, 'Sensor Hand with fingerjack and gyro-compass; the hand looks reasonably normal.', 'Fully loaded Violator SAMAS (all standard weapons and mini-missiles); a pair of Vibro-Knives; a Q1-02 Stopper ion pistol; a Q2-20 laser and grenade launcher with bayonet; a Q4-44 Drummer shotgun (carried even in V-SAM); a crate of 144 plasma mini-missiles; a crate of 144 armor piercing missiles; plenty of E-Clips and an E-Clip recharging unit; a variety of explosives; two Type-One Fusion Blocks. Armor: V-SAM, standard military body armor (80 M.D.C.), and Plain Clothes Armor (28 M.D.C.); also a Bobcat Hovercycle, language translator, laser distancer, RMK and IRMSS robot medical systems, first-aid kit, and standard Special Forces field gear.', NULL, 'Stern, driven and intensely private, an excellent tactician who keeps her feelings hidden except with her mentor Robert Carlye; would turn paranoid and morose if she felt betrayed by him.', 'Robert Carlye (mentor and confidant), Viper Delta Platoon, and the Children of Freedom (COF).', 'Implied: the Coalition States (her former service) and, per her backstory, the D-Bee pirates who killed her parents.', 'Captain Jeunet is the renegade ex-CS Special Forces officer who commands Viper Delta and provides the military muscle behind Robert Carlyes Children of Freedom.', 'Rifts World Book 22: Free Quebec p.173-174');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'kenneth-sprite', 'Kenneth Sprite', NULL, 'General of the 1st Apocalyptic Cavalry ("Crying Death")', 'rifts', 'Human', 'Gunslinger', 9, 'Aberrant evil', '40 years old', NULL, NULL, '{"IQ":11,"ME":15,"MA":14,"PS":14,"PP":22,"PE":23,"PB":20,"Spd":24}', 71, 67, NULL, 180, NULL, NULL, 13, '{"attacks":7,"strike":6,"parry":9,"dodge":9,"pull":7,"roll":3,"disarm":2}', 'Boxing and hand to hand: expert; plus 8 to strike when using revolvers or pistols; paired weapons and sharpshooting with revolvers and pistols; plus 5 to a fast draw; plus 2 to disarm on a called shot; plus 4 to save vs magic; plus 2 to save vs possession and mind control; plus 7 to save vs Horror Factor.', NULL, 'No percentile skills printed on this page for Sprite himself; his combat skills (boxing, hand to hand: expert) are listed above.', NULL, NULL, NULL, NULL, 'Clock calendar implant.', 'Usually seen in the blue and gold garb of a 1st Apocalyptic Cavalry General (an M.D.C. overcoat with light armor underneath); carries two Remi six-shooters, a pair of Wilks laser pistols (3D6 M.D. each), and a BigBore sawed-off at all times; also has an NG-Particle beam rifle and a Wilks laser pulse rifle.', 'The 1st Cavalry typically has access to 57,000 in Universal credits at any given time and millions in weapons, vehicles and equipment; Sprite himself is not interested in money, profit or fame.', 'A calm, fatherly-seeming but merciless zealot who believes himself a good man doing a dirty, necessary job, and weeps after every execution he carries out.', 'The entire 1st Apocalyptic Cavalry, who would follow him into hell; dozens of towns and thousands of people who regard him as a hero; the Coalition States tacitly aids him.', 'Most D-bees, who fear him as a boogey-man; the Lyn-Srial, Cyber-Knights, and Justice Rangers oppose his methods, though they have not fully turned on him.', 'General Kenneth Sprite is the vengeance-driven founder and commander of the 1st Apocalyptic Cavalry, a vigilante army that hunts D-bees and outlaws across the New West.', 'Rifts World Book 14: New West p.27-28');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'captain-nemo-2', 'Captain Nemo-2', 'Nemo Dobson', 'Commander of the USS Ticonderoga and the New Navy', 'rifts', 'Human descent (immortal, now a supernatural M.D.C. being)', 'Sea Titan R.C.C.', 14, 'Scrupulous', 'Appears late twenties, actually close to three hundred years old', NULL, NULL, '{"IQ":17,"ME":19,"MA":24,"PS":32,"PP":22,"PE":23,"PB":17,"Spd":19}', NULL, NULL, 163, 27, NULL, NULL, NULL, '{"attacks":6,"initiative":1,"strike":6,"parry":11,"dodge":11,"roll":4,"pull":3,"damage":21}', 'Horror Factor is printed as none to most humans, but 10 to low ranking/inexperienced naut''yll, intelligent sea monsters, and aquatic D-bees who know his reputation -- left null as a field since it is conditional. The plus 21 M.D. combat entry is from supernatural P.S.; he also has supernatural endurance, plus 2 save vs psionic attack, plus 5 save vs magic and poison/potions, 80 percent to evoke trust or intimidation, 35 percent to impress/charm, karate style kick (1D8), jump kick (critical strike), leap attack (critical strike), entangle, judo style body throw, and critical strike or knock-out/stun on an unmodified 18, 19 or 20.', '[{"name":"Radio: Basic","pct":98},{"name":"Radio: Scrambler","pct":98},{"name":"Computer Operation","pct":98},{"name":"Basic Math","pct":98},{"name":"Advanced Math","pct":98},{"name":"Detect Ambush","pct":98},{"name":"Demon and Monster Lore","pct":98},{"name":"Swimming","pct":98},{"name":"SCUBA","pct":98},{"name":"Pilot Motorboats","pct":98},{"name":"Pilot Ships","pct":98},{"name":"Pilot Submersibles","pct":98},{"name":"Pilot Robot: Basic","pct":98},{"name":"Navigation","pct":98},{"name":"Read Sensory Equipment","pct":98},{"name":"Weapon Systems","pct":98},{"name":"Astronomy","pct":95},{"name":"Land Navigation","pct":79},{"name":"Intelligence","pct":75},{"name":"Basic Electronics","pct":80},{"name":"Magic Lore","pct":79},{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Language: Chinese","pct":83},{"name":"Language: Naut''yll","pct":83},{"name":"Language: Euro","pct":58}]', 'Pilot: Robots and Power Armor and Robot Combat Elite: Semper Fi APA-15 Amphibious Power Armor also printed at 98%, plus Boxing. Combat abilities: Hand to Hand: Martial Arts. Weapon Proficiencies: W.P. Blunt (12th level), W.P. Automatic Pistol, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy (the last four all at 14th level proficiency).', 'Does not need to breathe, drink or eat to survive; immune to all normal (non-magic/supernatural) poisons and toxins; impervious to all known diseases; possesses supernatural strength and endurance; regenerates 1D4x10 M.D.C. per minute (4 melee rounds); can regrow lost limbs and organs in 2D6 hours.', 'Knows several magic countermeasures and the uses of magic in combat, but has no spell casting abilities.', NULL, NULL, NULL, 'Has access to ALL weapons and equipment of the New Navy, including power armor, weapons and vehicles; commands the USS Ticonderoga.', NULL, 'A tough, stern commander capable of enormous empathy and sensitivity; jokes with subordinates but expects unquestioning obedience in an emergency unless an officer has better information, in which case he wants initiative shown; keeps a guarded personal distance despite genuine camaraderie.', NULL, 'Implied: naut''yll, hostile sea monsters, and other threats to Earths oceans that the New Navy opposes (per the surrounding Horror Factor note); no explicit Enemies field is printed.', 'Captain Nemo-2 (Nemo Dobson) is the nearly three-century-old immortal commander of the USS Ticonderoga and living symbol of the New Navy.', 'Rifts World Book 7: Underseas p.110-111');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'old-man-morozko', 'Old Man Morozko', NULL, 'King of the Frost Demons (a demon lord; elsewhere called Lord of the Frost Demons)', 'rifts', NULL, NULL, 12, 'Anarchist', NULL, NULL, NULL, NULL, NULL, NULL, 2000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Possesses all the magic known to the greater Frost Demons, plus all level 1-3, and 15th level wizard spells.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Old Man Morozko is the anarchist demon lord who rules over the Frost Demons; he rarely interferes directly in mortal affairs.', 'Rifts World Book 18: Mystic Russia p.48');

