-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 16 notable NPCs are in' AS assertion, count(*) AS got, 16 AS want
  FROM notable_npcs WHERE slug IN ('vanessa-death-giver', 'angel-redstone', 'cherub-redstone', 'cagliostro-smith', 'slayer-dragon-juicer', 'george-hornesby', 'julian-the-first', 'bloodmist', 'brok-redman', 'cracius-the-cunning', 'hugh-madding', 'jacques-lefevre', 'elaine-jeunet', 'kenneth-sprite', 'captain-nemo-2', 'old-man-morozko');
SELECT 'and their 29 attacks' AS assertion, count(*) AS got, 29 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('vanessa-death-giver', 'angel-redstone', 'cherub-redstone', 'cagliostro-smith', 'slayer-dragon-juicer', 'george-hornesby', 'julian-the-first', 'bloodmist', 'brok-redman', 'cracius-the-cunning', 'hugh-madding', 'jacques-lefevre', 'elaine-jeunet', 'kenneth-sprite', 'captain-nemo-2', 'old-man-morozko');

